def is_prime(n):
    """
    Kiểm tra xem một số nguyên dương n có phải là số nguyên tố hay không.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False

    # Chỉ cần kiểm tra các số có dạng 6k +/- 1 đến căn bậc hai của n
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

